def render_section(sec):
 title,body,kind,details=sec
 right=''
 if kind=='list':right='<ul class="text-list">'+''.join(f'<li>{escape(name)}<span>{escape(desc)}</span></li>' for name,desc in details)+'</ul>'
 if kind=='note':right=f'<div class="page-note">{escape(details)}</div>'
 if kind=='link':label,href=details.split('|');right=f'<a class="inline-link" href="{href}">{escape(label)} <span aria-hidden="true">↗</span></a>'
 return f'<section class="page-section"><div><p class="eyebrow">{escape(title.upper())}</p><h2>{escape(title)}</h2></div><div><p>{escape(body)}</p>{right}</div></section>'
